refreshView(newTView, newLView, newTView.template, instance);

// after (Angular 20): executed inside the component's NgZone
const zone = lView[INJECTOR].get(NgZone, null);
const recreate = () => { /* getOrCreateComponentTView, createLView, renderView, refreshView ... */ };
if (zone === null) {
  recreate();
} else {
  zone.run(recreate);
}
```

