// Demonstrating extraction of parenthesized dependencies
const token = new InjectionToken<number>('TEST');
const value = 123;
const otherValue = 321;

@Component({
  template: '',
  providers: [{
    provide: token,
    // Before: dependencies 'value' and 'otherValue' were missed due to parentheses
    // After: they are correctly extracted
    useFactory: () => [(value), ((((otherValue))))]
  }]
})
export class Cmp {}
```

