```TypeScript
// Before (Angular 19 rxResource)
const myResource = rxResource({
  request: () => params(),
  loader: ({ request }) => myService.getData(request)
});

// After (Angular 20 rxResource)
const myResource = rxResource({
  params: () => params(),
  stream: ({ params }) => myService.getData(params)
});
```

